const BOT_TOKEN = '8700054453:AAGu-Xp830OS9FOvdV-2w7ll_tbOuI3Lb18';
const results = [];
for (const item of $input.all()) {
  const update = item.json;
  let chatId, text = '', callbackData = '', isCallback = false, callbackQueryId = '';
  if (update.callback_query) {
    isCallback = true;
    chatId = update.callback_query.message.chat.id;
    callbackData = update.callback_query.data || '';
    callbackQueryId = update.callback_query.id;
    try { await helpers.httpRequest({ method:'POST', url:`https://api.telegram.org/bot${BOT_TOKEN}/answerCallbackQuery`, headers:{'Content-Type':'application/json'}, body:JSON.stringify({callback_query_id:callbackQueryId}) }); } catch(e) {}
  } else if (update.message) {
    chatId = update.message.chat.id;
    text = (update.message.text || '').trim();
  } else { continue; }

  let route = 'main_menu', extra = '';
  if (isCallback) {
    const cb = callbackData;
    if (['main_menu','status','campaign','scrape','campaigns','report','pending','human'].includes(cb)) route = cb;
    else if (cb.startsWith('campaign_')) { extra = cb.replace('campaign_',''); route = 'launch_campaign'; }
    else if (cb.startsWith('demo_'))     { extra = cb.replace('demo_',''); route = 'run_demo'; }
    else if (cb.startsWith('report_'))   { extra = cb.replace('report_',''); route = 'run_report'; }
    else route = 'main_menu';
  } else {
    if (!text || text === '/start') { route = 'main_menu'; }
    else {
      const parts = text.replace(/^\/scrape ?/,'').trim().split(' ');
      const last = parts[parts.length-1];
      if (!isNaN(last) && parseInt(last)>0 && parts.length>=2) { extra = parts.join(' '); route = 'run_scrape'; }
      else { route = 'main_menu'; }
    }
  }
  results.push({ json: { chatId, text, callbackData, isCallback, route, extra } });
}
return results;

